// Salon photos, embedded as base64 data URIs.
// The GitHub push route used for this repo is text-only and rejects
// binary files, so the original JPEGs in public/images/ cannot be
// pushed to the repo — these data URIs are what Vercel actually serves.
// Each photo was optimised to 1200x800, JPEG quality 70, before encoding.
// To swap in real salon photos: replace the data URI strings below,
// or upload JPEGs to public/images/ and point the map back at the files.
// Original full-size (1920x1280) JPEGs are kept in public/images/ for local use.
const IMAGES = {
  hero: "data:image/jpeg;base64,",
  hairCut: "data:image/jpeg;base64,",
  hairSpa: "data:image/jpeg;base64,",
  mensCut: "data:image/jpeg;base64,",
};
